'use strict';
// History SQL is a separate source projection; schema DDL and business KB never enter it.
state.historySQL=null;
function historyDBKey(){return (state.dataset||'BIRD-History')+'::'+state.db.database;}
function localHistoryProjection(db){const objects=db.ontology.objects,edges=db.ontology.edges;return db.ontology.sources.filter(s=>s.extractor_version!==undefined&&s.history_id&&typeof s.sql==='string').map((s,i)=>{const refs=[s.evidence_id,s.history_id].filter(Boolean),supported=objects.filter(o=>(o.evidence_ids||[]).some(ref=>refs.includes(ref)));return {key:String(i),history_id:s.history_id,sql:s.sql,evidence_ids:refs,native_sources:['native semantic state.records'],metadata:s.dialect?[{dialect:s.dialect}]:[],supported_object_ids:supported.map(o=>o.id),supported_physical_identifiers:[...new Set(supported.filter(o=>o.kind==='column').flatMap(o=>o.physical_identifiers||[]))],supported_business_ids:supported.filter(o=>['metric','binding','predicate','program'].includes(o.kind)).map(o=>o.id),supported_edge_indices:edges.map((e,index)=>(e.provenance_ids||[]).some(ref=>refs.includes(ref))?index:-1).filter(index=>index>=0)};});}
async function loadHistorySQL(){const view=state.historySQL;if(!view)return null;if(view.records)return view;if(view.loading)return view.loading;const key=view.dbKey;view.loading=(async()=>{const payload=state.db.history_sql_path?await json(state.db.history_sql_path):{records:localHistoryProjection(state.db)};if(!state.historySQL||state.historySQL.dbKey!==key)return null;view.records=payload.records;return view;})();return view.loading;}
function mountHistorySQL(){if(!state.db)return;const dbKey=historyDBKey();state.historySQL={dbKey,records:null,page:0,query:'',selected:null,current:new Set(),pageSize:20};$('#history-sql-block')?.remove();const count=state.db.history_sql_count??localHistoryProjection(state.db).length;const block=document.createElement('details');block.id='history-sql-block';block.className='sr-native-block';block.innerHTML=`<summary>History SQL / 可查看的历史SQL：<span id="history-total">${count}</span>条<span id="history-run-label" class="sr-history-run-label"></span></summary><div class="sr-history-controls"><input id="history-search" placeholder="Search original ID or SQL / 搜索历史SQL" aria-label="Search history SQL"><div class="sr-history-pager"><button id="history-prev" class="ghost">←</button><span id="history-page" class="sr-note"></span><button id="history-next" class="ghost">→</button></div></div><div id="history-records"><p class="sr-note">${count?'Expand to load saved history SQL.':'当前存档未包含历史SQL文本。No history SQL text is included in this archive.'}</p></div><div id="history-support"></div>`;$('#schemawrap').appendChild(block);block.ontoggle=async()=>{if(!block.open)return;const view=await loadHistorySQL();if(view)drawHistorySQL();};$('#history-search').oninput=async()=>{const view=await loadHistorySQL();if(view){view.query=$('#history-search').value;view.page=0;drawHistorySQL();}};$('#history-prev').onclick=()=>{const view=state.historySQL;view.page=Math.max(0,view.page-1);drawHistorySQL();};$('#history-next').onclick=()=>{state.historySQL.page++;drawHistorySQL();};}
function drawHistorySQL(){const view=state.historySQL;if(!view?.records)return;const query=view.query.toLowerCase();const matching=view.records.filter(row=>[row.history_id,row.sql].join(' ').toLowerCase().includes(query));const pages=Math.max(1,Math.ceil(matching.length/view.pageSize));view.page=Math.min(view.page,pages-1);const rows=matching.slice(view.page*view.pageSize,(view.page+1)*view.pageSize);$('#history-page').textContent=`${matching.length} records · ${view.page+1}/${pages}`;$('#history-prev').disabled=view.page===0;$('#history-next').disabled=view.page===pages-1;$('#history-records').innerHTML=rows.length?rows.map(row=>`<details class="sr-json sr-history-record ${view.current.has(row.key)?'sr-history-current':''} ${view.selected===row.key?'sr-history-selected':''}" data-history-key="${esc(row.key)}"><summary><span class="sr-source-id">${esc(row.history_id)}</span><span class="sr-history-link-count">${row.supported_physical_identifiers.length} cols · ${row.supported_edge_indices.length} joins · ${row.supported_business_ids.length} definitions</span></summary>${code(row.sql)}${details('Saved source metadata',{original_history_id:row.history_id,evidence_ids:row.evidence_ids,native_sources:row.native_sources,metadata:row.metadata,original_physical_identifiers:row.explicit_physical_identifiers,additional_source_identifiers:row.unbound_source_identifiers})}</details>`).join(''):'<p class="sr-note">'+(view.records.length?'No matching history SQL.':'当前存档未包含历史SQL文本。No history SQL text is included in this archive.')+'</p>';document.querySelectorAll('[data-history-key]').forEach(record=>record.ontoggle=()=>{if(record.open)selectHistorySQL(record.dataset.historyKey);});if(view.selected)showHistorySupport(view.records.find(row=>row.key===view.selected));}
function selectHistorySQL(key){const view=state.historySQL;if(!view?.records)return;view.selected=key;document.querySelectorAll('[data-history-key]').forEach(node=>node.classList.toggle('sr-history-selected',node.dataset.historyKey===key));showHistorySupport(view.records.find(row=>row.key===key));}
function showHistorySupport(record){if(!record)return;const ontology=state.db.ontology,objects=new Map(ontology.objects.map(o=>[o.id,o]));const columns=columnRows();const physical=new Set(record.supported_physical_identifiers),business=new Set(record.supported_business_ids),edgeKeys=new Set(record.supported_edge_indices.map(i=>{const e=ontology.edges[i];return e?e.left+'↔'+e.right:'';}));const businessObjects=record.supported_business_ids.map(id=>objects.get(id)).filter(Boolean);const links=record.supported_edge_indices.map(i=>ontology.edges[i]).filter(Boolean);$('#history-support').innerHTML=`<div class="sr-history-support-panel"><h4>Supported by ${esc(record.history_id)}</h4><div class="sr-note">${physical.size} recovered-column bindings · ${links.length} relationship bindings · ${businessObjects.length} business definitions</div><details class="sr-json"><summary>Recovered columns / 恢复列名 · ${physical.size}</summary>${[...physical].map(id=>{const c=columns.find(c=>c.physical===id);return `<div class="sr-history-supported-item"><code>${esc(id)}</code><span>${esc(c?.aliases.join(' / ')||'No saved alias')}</span></div>`;}).join('')}</details><details class="sr-json"><summary>Joins / 连接 · ${links.length}</summary>${links.map(e=>`<div class="sr-history-supported-item">${esc(e.left)} ↔ ${esc(e.right)}</div>${details('Saved edge evidence',e)}`).join('')}</details><details class="sr-json"><summary>Business scope & grain / 业务口径 · ${businessObjects.length}</summary>${businessObjects.map(o=>details((o.aliases||[]).join(' / ')||o.kind,{kind:o.kind,formula:o.expression,grain:o.grain,scope:o.row_context,upstream_scopes:o.upstream_scopes,evidence_ids:o.evidence_ids})).join('')}</details></div>`;document.querySelectorAll('[data-column]').forEach(el=>el.classList.toggle('sr-history-supported',physical.has(el.dataset.column)));document.querySelectorAll('[data-semantic-id]').forEach(el=>el.classList.toggle('sr-history-supported',business.has(el.dataset.semanticId)));document.querySelectorAll('[data-edge-left]').forEach(el=>el.classList.toggle('sr-history-supported-edge',edgeKeys.has(el.dataset.edgeLeft+'↔'+el.dataset.edgeRight)));}
async function highlightCurrentHistorySQL(sources){const dbKey=historyDBKey(),view=await loadHistorySQL();if(!view||view.dbKey!==dbKey)return;const current=view.records.filter(record=>sources.some(s=>record.sql===s.sql&&record.evidence_ids.some(id=>id===s.evidence_id||id===s.history_id)));view.current=new Set(current.map(row=>row.key));$('#history-run-label').textContent=current.length?' · current SQL: '+current.map(row=>row.history_id).join(', '):'';if(current.length){$('#history-sql-block').open=true;view.query='';$('#history-search').value='';view.page=Math.floor(view.records.findIndex(row=>row.key===current[0].key)/view.pageSize);drawHistorySQL();}}
const middleWithHistory=drawMiddle;drawMiddle=function(){middleWithHistory();mountHistorySQL();};
if(state.db)mountHistorySQL();
